-- Create main customer table
CREATE TABLE IF NOT EXISTS customer (
    c.customer_id SERIAL PRIMARY KEY,
    c.customer_name VARCHAR(255) NOT NULL,
    c.email VARCHAR(255) NOT NULL UNIQUE
);

-- Create products table
CREATE TABLE IF NOT EXISTS products (
    product_id SERIAL PRIMARY KEY,
    product_name VARCHAR(255) NOT NULL
);

-- Create payment_history table
CREATE TABLE IF NOT EXISTS payment_history (
    payment_id SERIAL PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customer(customer_id) ON DELETE CASCADE,
    product_id INT NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,
    status VARCHAR(50) NOT NULL
);

-- Create customer_complaint table
CREATE TABLE IF NOT EXISTS customer_complaint (
    complaint_id SERIAL PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customer(customer_id) ON DELETE CASCADE,
    complaint TEXT NOT NULL
);

-- 1. Drop existing tables to clear conflicting column definitions
DROP TABLE IF EXISTS customer_complaint CASCADE;
DROP TABLE IF EXISTS payment_history CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS customer CASCADE;

-- 2. Create customer table
CREATE TABLE customer (
    customer_id SERIAL PRIMARY KEY,
    customer_name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE
);

-- 3. Create products table
CREATE TABLE products (
    product_id SERIAL PRIMARY KEY,
    product_name VARCHAR(255) NOT NULL
);

-- 4. Create payment_history table with customer_id
CREATE TABLE payment_history (
    payment_id SERIAL PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customer(customer_id) ON DELETE CASCADE,
    product_id INT NOT NULL REFERENCES products(product_id) ON DELETE CASCADE,
    status VARCHAR(50) NOT NULL
);

-- 5. Create customer_complaint table
CREATE TABLE customer_complaint (
    complaint_id SERIAL PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customer(customer_id) ON DELETE CASCADE,
    complaint TEXT NOT NULL
);
